    g:[
      {more:["There is a supermarket next to my building.","There are three cafés across from the park.","Is there a bus stop near here?","There aren’t any cinemas in my neighbourhood.","There’s a pharmacy on the corner, behind the church.","How many parks are there in your city?"],
       fix:[{wrong:"There is two banks.", right:"There are two banks.", why:"A plural noun needs “there are”."},
            {wrong:"It is a park near my house.", right:"There is a park near my house.", why:"“There is” says something exists; “it is” identifies something already mentioned."},
            {wrong:"There are a lot of traffic.", right:"There is a lot of traffic.", why:"“Traffic” is uncountable, so it takes “there is”."}],
       drill:{name:"Map it", prompt:"Look around the room (or at a map) and say one sentence for each preposition.",
        items:["next to","in front of","behind","across from","between"]},
       dialogue:[{sp:"A", line:"Is there a pharmacy near here?"},{sp:"B", line:"Yes, there’s one across from the bank."},{sp:"A", line:"Are there any cash machines on this street?"},{sp:"B", line:"There aren’t any here, but there are two in the mall."}],
       contrast:{title:"there is / there are / it is", cols:["Form","Use","Example"], rows:[["there is","one thing exists","There is a park."],["there are","several exist","There are two parks."],["there is + uncountable","amount exists","There is a lot of noise."],["it is","describes a known thing","It is very big."],["question","Is/Are there…?","Are there any shops?"]]},
       sound:"“There’s” and “there are” sound almost the same in fast speech — the plural noun is what tells the listener which one you said. Say the noun clearly."},
      {more:["How many rooms are there in your house?","How much traffic is there in the morning?","There aren’t many parks in my area.","There isn’t much noise at night.","Only a few shops open on Sundays.","There’s very little space in the centre."],
       fix:[{wrong:"How many traffic is there?", right:"How much traffic is there?", why:"“Traffic” is uncountable, so we use “how much”."},
            {wrong:"There aren’t much shops.", right:"There aren’t many shops.", why:"“Many” goes with countable plurals."},
            {wrong:"There is few space.", right:"There is little space.", why:"“Few” is for countable nouns, “little” for uncountable."}],
       drill:{name:"Countable or not?", prompt:"Ask the question with how much or how many.",
        items:["___ people live here?","___ traffic is there?","___ restaurants are there?","___ noise is there at night?","___ parks are there near you?"]},
       dialogue:[{sp:"A", line:"How many people live in your building?"},{sp:"B", line:"About forty. But there isn’t much space for cars."},{sp:"A", line:"How much noise is there at night?"},{sp:"B", line:"Very little — it’s a quiet street."}],
       contrast:{title:"countable vs. uncountable", cols:["","Countable","Uncountable"], rows:[["question","How many?","How much?"],["a lot","many","much"],["small amount","a few","a little"],["very small","few","little"],["examples","shops, parks, people","traffic, noise, space"]]},
       sound:"“How much” and “how many” are said as one unit with the stress on MUCH / MAny."} ],
    dyn:[
      {name:"Blind map", mode:"Pairs", minutes:"12 min", how:"Partner A has a simple map with eight places; Partner B has an empty grid. A describes with “There is… next to…” until B’s map matches. No pointing, no naming grid squares.", payoff:"Prepositions of place become the only tool that works."},
      {name:"Neighbourhood advert", mode:"Groups of 3", minutes:"13 min", how:"Groups invent a neighbourhood and sell it to the class in 60 seconds using at least six “there is / there are” sentences. The class votes on where they would live.", payoff:"Repetition inside a persuasive task."},
      {name:"How much, how many", mode:"Whole class, moving", minutes:"10 min", how:"Twelve cards with nouns (traffic, shops, noise, parks…). Students collect cards by asking a correct question about each one to a classmate.", payoff:"Sorts countable from uncountable through use, not rules."},
      {name:"Spot the difference", mode:"Pairs", minutes:"9 min", how:"Two similar street pictures. Students find six differences, each stated as “In my picture there is… but in yours there are…”.", payoff:"Forces the singular/plural choice in every sentence."} ],
    wr:{title:"My street", brief:"Describe your street or neighbourhood: what there is, what there isn’t, and how much traffic and noise there is. Use at least four prepositions of place.", length:"8 sentences · about 95 words", criteria:["“There is” and “there are” agree with the noun.","Four different prepositions of place.","“How much / how many” used correctly if you include a question."]},
    hw:{title:"Draw and label", brief:"", task:"Draw a simple map of the five places closest to your home. Label them, then write five sentences with “there is / there are” and a preposition of place."},
    test:[
      {q:"___ any restaurants near your house?", options:["Are there","Is there","There are"], answer:0, explain:"“Restaurants” is plural and it is a question, so we invert: “Are there any…?”"},
      {q:"___ traffic is there in the morning?", options:["How much","How many","How long"], answer:0, explain:"“Traffic” is uncountable, so “how much”."},
      {q:"The bank is ___ the pharmacy.", options:["next to","next","near of"], answer:0, explain:"The preposition is “next to”."},
      {q:"There ___ a lot of noise at night.", options:["isn’t","aren’t","don’t"], answer:0, explain:"“Noise” is uncountable, so it takes “there isn’t”."},
      {q:"There are only ___ shops on my street.", options:["a few","a little","much"], answer:0, explain:"“Shops” is countable, so “a few”."} ],
