       contrast:{title:"Agreeing correctly", cols:["Original","Positive agreement","Negative agreement"], rows:[["I am tired.","So am I.","—"],["I like it.","So do I.","—"],["I went.","So did I.","—"],["I have finished.","So have I.","—"],["I don’t like it.","—","Neither do I. / I don’t either."],["I can’t come.","—","Neither can I. / I can’t either."]]},
