       contrast:{title:"How certain is the plan?", cols:["Form","Certainty","Example"], rows:[["I’m going to…","decided","I’m going to start in March."],["I’m -ing (time + place)","arranged","I’m starting on 3 March."],["I plan to / I need to","likely","I plan to start soon."],["I want to","wish, undated","I want to start."],["I hope to / I’d like to","distant, polite","I hope to start one day."],["I decided not to…","cancelled","I decided not to start."]]},
